{
  "summary": "No previously reported findings have been addressed in the current code base – all high/medium issues from earlier rounds remain open. In addition, two new concerns were identified: (1) receipt photo capture does not limit image size, opening the app to potential storage‑exhaustion attacks; (2) the encrypted‑store key is never removed when the user invokes the \"Delete all data\" flow, which could allow decryption of residual data that might survive a table wipe. Both are medium‑severity code findings that should be mitigated before production release.",
  "previous": [
    {
      "id": "high-deps-braces-2026-93687",
      "status": "open",
      "severity": "high",
      "severity_change_reason": "No change; the vulnerable braces 3.0.3 version is still present in lockfile and no fix is available."
    },
    {
      "id": "high-deps-node-forge-2026-85393",
      "status": "open",
      "severity": "high",
      "severity_change_reason": "No change; node‑forge 1.4.0 remains a transitive dependency with no patch yet."
    },
    {
      "id": "medium-deps-uuid-2026-41907",
      "status": "open",
      "severity": "medium",
      "severity_change_reason": "No change; the lockfile still pulls in uuid 7.0.3 which is vulnerable. Package.json lists a newer version but the lockfile has not been updated."
    },
    {
      "id": "medium-deps-sprintf-js-2026-97058",
      "status": "open",
      "severity": "medium",
      "severity_change_reason": "No change; sprintf‑js remains vulnerable and no safe version is used."
    },
    {
      "id": "high-csv-injection",
      "status": "open",
      "severity": "high",
      "severity_change_reason": "No change; CSV export (src/lib/exportCsv.ts) concatenates raw user fields without sanitising leading \"=,+,-,@\" characters."
    },
    {
      "id": "high-pdf-html-injection",
      "status": "open",
      "severity": "high",
      "severity_change_reason": "No change; PDF export (src/lib/exportPdf.ts) interpolates user‑provided text into HTML without escaping, allowing HTML/script injection."
    },
    {
      "id": "medium-backup-passphrase-policy",
      "status": "open",
      "severity": "medium",
      "severity_change_reason": "No change; backup UI accepts any non‑empty passphrase and does not enforce complexity or minimum length."
    },
    {
      "id": "medium-web-key-storage",
      "status": "open",
      "severity": "medium",
      "severity_change_reason": "No change; the web fallback storage implementation (src/lib/storage/device.web.ts) persists the encryption key in localStorage, which is insecure."
    },
    {
      "id": "medium-temp-backup-file-deletion",
      "status": "open",
      "severity": "medium",
      "severity_change_reason": "No change; after creating an encrypted backup the temporary file is never removed, leaving the encrypted blob on the device."
    },
    {
      "id": "medium-input-validation-numeric",
      "status": "open",
      "severity": "medium",
      "severity_change_reason": "No change; numeric fields (amount, mileage, rates, tax rate) are not validated for range or type, allowing negative or absurd values."
    },
    {
      "id": "deployment-csp-header",
      "status": "open",
      "severity": "medium",
      "severity_change_reason": "No change; the optional web build does not include a CSP meta/header, exposing it to injection if ever served."
    }
  ],
  "findings": [
    {
      "id": "medium-image-size-validation-2026-00001",
      "severity": "medium",
      "where": "code",
      "file": "src/lib/photoPicker.ts",
      "issue": "Receipt photo capture via expo-image-picker accepts arbitrarily large image files. A malicious user could take extremely high‑resolution photos, exhausting device storage and potentially causing the app to become unusable.",
      "fix": "Enforce a maximum image size or resolution when picking/taking a photo (e.g., set `quality` or `allowsEditing` options, check `FileSystem.getInfoAsync` for size, reject or down‑scale images above a safe threshold)."
    },
    {
      "id": "medium-key-persistence-after-data-delete-2026-00002",
      "severity": "medium",
      "where": "code",
      "file": "src/lib/dataReset.ts",
      "issue": "The \"Delete all data\" action clears the SQLite tables but does not delete the encryption key stored in expo‑secure‑store. If any encrypted remnants remain on disk, the retained key could be used to recover them.",
      "fix": "When performing a full data wipe, also delete the encryption key from SecureStore (e.g., `SecureStore.deleteItemAsync(KEY_NAME)`) and optionally overwrite the database file to prevent residual data recovery."
    }
  ]
